import re
M=open("The_Method_1_6-2.md",encoding="utf-8").read()
C=open("The_Method_1_6___Mathematical_Compendium-2.md",encoding="utf-8").read()
R=open("The_Method_1_6___The_Register-2.md",encoding="utf-8").read()
# Register number universe
regnums=set()
for l in R.split("\n"):
    m=re.match(r"### ([\d,\s]+)",l)
    if m: regnums|={int(x) for x in re.findall(r"\d+",m.group(1))}
# excised numbers
exc=set()
for m in re.finditer(r"<!-- EXCISED ([\d,\s]+) :",open("WORKING-REGISTER.md",encoding="utf-8").read()):
    exc|={int(x) for x in re.findall(r"\d+",m.group(1))}
cited=set()
for m in re.finditer(r"registers? ([\d,\s and]+)",C):
    cited|={int(x) for x in re.findall(r"\d{2,4}",m.group(1))}
print("register citations distinct:",len(cited))
print("  DANGLING (not a Register number):",sorted(cited-regnums))
print("  CITING AN EXCISED entry       :",sorted(cited&exc))
# main volume heading locator universe
mainloc=set()
for l in M.split("\n"):
    h=re.match(r"^#{1,6} +([0-9]+(?:\.[0-9]+)*|Appendix [A-Z])\b",l)
    if h: mainloc.add(h.group(1))
    h2=re.match(r"^#{1,6} +([A-Z]\.[0-9]+(?:\.[0-9]+)*)\b",l)
    if h2: mainloc.add(h2.group(1))
print("main locator universe:",len(mainloc),"eg",sorted(list(mainloc))[:6])
selfloc=set()
for l in C.split("\n"):
    h=re.match(r"^#{1,6} +([0-9A-Z]+(?:\.[0-9]+)*)\b",l)
    if h: selfloc.add(h.group(1))
locs=sorted(set(re.findall(r"§([0-9A-Z]+(?:\.[0-9]+)*)",C)))
def res(x):
    if x in mainloc or x in selfloc: return True
    return any(m.startswith(x+".") for m in mainloc|selfloc)
bad=[x for x in locs if not res(x)]
print("distinct § locators:",len(locs),"| UNRESOLVED:",len(bad))
print("  ",bad[:25])
ch=sorted(set(int(x) for x in re.findall(r"Chapter (\d+)",C)))
mainch={int(m.group(1)) for m in re.finditer(r"^#{1,3} +(\d+)[ .]",M,re.M)}
print("Chapters cited:",ch,"| unresolved:",[c for c in ch if c not in mainch])
